import{_ as e,c as r,o as t,a4 as n}from"./chunks/framework.0Tb_0pc6.js";const o="/ai/daily/2026-05-17/news_01krsqxw8tf6avf0fyqarhsvyc.avif",s="/ai/daily/2026-05-17/news_01krswvcwdf6avf0gm4xk81dv7.avif",i="/ai/daily/2026-05-17/news_01krsqx9pkf6avf0ejzh8cr66w.avif",l="/ai/daily/2026-05-17/news_01krsqxbzyf6avf0erfh45xjb5.avif",h="/ai/daily/2026-05-17/news_01krsqxe5sf6avf0f6514qq5st.avif",_=JSON.parse('{"title":"AI大事件 2026/5/17","description":"","frontmatter":{"linkTitle":"05-17 AI大事件","title":"AI大事件 2026/5/17","weight":15,"breadcrumbs":false,"comments":true,"description":""},"headers":[],"relativePath":"AI/daily/cn/2026-05/2026-05-17.md","filePath":"AI/daily/cn/2026-05/2026-05-17.md","lastUpdated":1779090350000}'),p={name:"AI/daily/cn/2026-05/2026-05-17.md"};function c(g,a,d,b,m,u){return t(),r("div",null,[...a[0]||(a[0]=[n(`<h1 align="center">2026-05-17 AI大事件</h1><h2 id="今日摘要" tabindex="-1"><strong>今日摘要</strong> <a class="header-anchor" href="#今日摘要" aria-label="Permalink to &quot;**今日摘要**&quot;">​</a></h2><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>OpenAI 史上最大规模重组：Brockman 夺权挂帅，三大产品线合并为统一组织 🚀</span></span>
<span class="line"><span>Anthropic 寻求 $900B 估值融资 $30-50B，年化收入 $45B 首超 OpenAI 🤑</span></span>
<span class="line"><span>GPT-5.5 网络安全能力匹敌 Mythos：CTF 成功率 71.4%，UK AISI 实测确认 🧠</span></span>
<span class="line"><span>蚂蚁百灵 Ring-2.6-1T 万亿参数开源，MIT 协议，基准全面超越 GPT-5.4 (๑•̀ㅂ•́)و✧</span></span>
<span class="line"><span>Mythos 辅助发现 macOS M5 内核漏洞，5 天绕过苹果 MIE 硬件安全 ⚠️</span></span>
<span class="line"><span>Notion 发布开发者平台 + ntn CLI，开发者工作空间迈向 Agent 原生 🛠️</span></span>
<span class="line"><span>美国 AI 岗位开始大规模裁员，技术冲击从理论进入实证阶段 ☁️</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br></div></div><h2 id="模型与产品更新" tabindex="-1">模型与产品更新 <a class="header-anchor" href="#模型与产品更新" aria-label="Permalink to &quot;模型与产品更新&quot;">​</a></h2><h3 id="_1-阿里健康发布「氢离子」ai-医学助手" tabindex="-1">1. 阿里健康发布「氢离子」AI 医学助手 <a class="header-anchor" href="#_1-阿里健康发布「氢离子」ai-医学助手" aria-label="Permalink to &quot;1. 阿里健康发布「氢离子」AI 医学助手&quot;">​</a></h3><p><strong>阿里健康</strong>发布了专注医生的医学 AI 工具「氢离子」，已独家签约<strong>顶刊 BMJ 海量医学文献</strong>。该助手可帮专家快速精准搜索，每句建议背后均有循证医学证据支撑，将文献阅读时间从两小时缩短到几分钟 🩺 来源：<a href="https://mp.weixin.qq.com/s?__biz=MzIzNjc1NzUzMw==&amp;mid=2247891178&amp;idx=1&amp;sn=dde06ec33d0bb3d63b7823b5654a18d3" target="_blank" rel="noreferrer">详情链接</a></p><h3 id="_2-英伟达发布-sana-wm-26-亿参数开源世界模型" tabindex="-1">2. 英伟达发布 SANA-WM 26 亿参数开源世界模型 <a class="header-anchor" href="#_2-英伟达发布-sana-wm-26-亿参数开源世界模型" aria-label="Permalink to &quot;2. 英伟达发布 SANA-WM 26 亿参数开源世界模型&quot;">​</a></h3><p><strong>NVIDIA</strong> 研究团队发布 <strong>SANA-WM</strong>，参数规模达 26 亿，专门用于生成长达 1 分钟、分辨率 720p 的视频，在 HN 社区获得 107 点热度 🎮 来源：<a href="https://nvlabs.github.io/Sana/WM" target="_blank" rel="noreferrer">项目主页</a></p><h3 id="_3-蚂蚁百灵-ring-2-6-1t-万亿参数推理模型开源" tabindex="-1">3. 蚂蚁百灵 Ring-2.6-1T 万亿参数推理模型开源 <a class="header-anchor" href="#_3-蚂蚁百灵-ring-2-6-1t-万亿参数推理模型开源" aria-label="Permalink to &quot;3. 蚂蚁百灵 Ring-2.6-1T 万亿参数推理模型开源&quot;">​</a></h3><p>蚂蚁集团 inclusionAI 正式开源万亿参数 MoE 推理模型 <strong>Ring-2.6-1T</strong>，以 <strong>MIT 协议</strong>发布，总参数约 1 万亿、每 token 激活约 63B。AIME 2026 得分 95.83、GPQA Diamond 88.27，基准全面超越 GPT-5.4。这是目前许可最宽松的万亿级推理模型 (๑•̀ㅂ•́)و✧ 来源：<a href="https://www.scmp.com/tech/tech-trends/article/3328425/chinese-fintech-giant-ant-group-releases-powerful-ai-model-rival-deepseek-and-openai" target="_blank" rel="noreferrer">SCMP 报道</a> · <a href="https://huggingface.co/inclusionAI/Ling-2.6-1T" target="_blank" rel="noreferrer">Hugging Face</a></p><h3 id="_4-notion-发布开发者平台及-ntn-cli" tabindex="-1">4. Notion 发布开发者平台及 ntn CLI <a class="header-anchor" href="#_4-notion-发布开发者平台及-ntn-cli" aria-label="Permalink to &quot;4. Notion 发布开发者平台及 ntn CLI&quot;">​</a></h3><p><strong>Notion</strong> 于 5 月 13 日正式推出 Developer Platform，包含 <code>ntn</code> CLI 工具、Workers 无服务器运行时（TypeScript）、Database Sync、Webhook Triggers 和 External Agents API。Beta 期免费至 8 月 11 日，让 Notion 从文档工具进化为可编程的 Agent 工作空间 🛠️ 来源：<a href="https://chatgate.ai/post/notion-developer-platform" target="_blank" rel="noreferrer">官方平台页</a> · <a href="https://byteiota.com/notion-developer-platform-workers-agent-api-2026/" target="_blank" rel="noreferrer">ntn CLI 文档</a></p><h3 id="_5-gpt-5-5-网络安全能力经实测匹敌-mythos" tabindex="-1">5. GPT-5.5 网络安全能力经实测匹敌 Mythos <a class="header-anchor" href="#_5-gpt-5-5-网络安全能力经实测匹敌-mythos" aria-label="Permalink to &quot;5. GPT-5.5 网络安全能力经实测匹敌 Mythos&quot;">​</a></h3><p><strong>UK AISI</strong> 发布独立评测：<strong>GPT-5.5</strong> 在最高难度 CTF 任务中成功率 <strong>71.4%</strong>（Mythos: 68.6%），逆向工程任务仅用 10 分 22 秒（人类专家需约 12 小时）。HackerOne 基准测试中漏报率降至仅 10%。OpenAI 已通过 TAC 计划向受信防御者开放 GPT-5.5-Cyber 🧠 来源：<a href="https://www.schneier.com/blog/archives/2026/05/openais-gpt-5-5-is-as-good-as-mythos-at-finding-security-vulnerabilities.html" target="_blank" rel="noreferrer">Schneier 分析</a> · <a href="https://www.hackerone.com/blog/vulnerability-exploitability-benchmark-gpt-5-5-vs-claude" target="_blank" rel="noreferrer">HackerOne 基准</a> · <a href="https://xbow.com/blog/mythos-like-hacking-open-to-all" target="_blank" rel="noreferrer">XBOW 测试</a></p><h3 id="_6-codex-支持自定义快捷键" tabindex="-1">6. Codex 支持自定义快捷键 <a class="header-anchor" href="#_6-codex-支持自定义快捷键" aria-label="Permalink to &quot;6. Codex 支持自定义快捷键&quot;">​</a></h3><p>OpenAI 开发者团队宣布 <strong>Codex 键盘快捷键</strong>现已支持自定义，用户可根据实际工作方式调整快捷键配置 ⌨️ 来源：<a href="https://x.com/OpenAIDevs/status/2055717793841221796" target="_blank" rel="noreferrer">官方公告</a></p><h2 id="前沿研究" tabindex="-1">前沿研究 <a class="header-anchor" href="#前沿研究" aria-label="Permalink to &quot;前沿研究&quot;">​</a></h2><h3 id="_1-大模型评测标准遭遇信任危机" tabindex="-1">1. 大模型评测标准遭遇信任危机 <a class="header-anchor" href="#_1-大模型评测标准遭遇信任危机" aria-label="Permalink to &quot;1. 大模型评测标准遭遇信任危机&quot;">​</a></h3><p>论文揭露了当前大模型跑分榜单的<strong>评价陷阱</strong>——许多排行榜其实只衡量表面行为，难以测出真实能力。选模型时别被虚高分数误导，构建真正厉害的智能体需要更严谨的评价体系 (・∀・) 来源：<a href="https://arxiv.org/abs/2605.14167" target="_blank" rel="noreferrer">论文</a></p><p><img src="`+o+'" alt="AI资讯：展示模型评价陷阱概念的学术论文架构图" loading="lazy"></p><h3 id="_2-gor-引用图谱驱动科研灵感生成" tabindex="-1">2. GoR：引用图谱驱动科研灵感生成 <a class="header-anchor" href="#_2-gor-引用图谱驱动科研灵感生成" aria-label="Permalink to &quot;2. GoR：引用图谱驱动科研灵感生成&quot;">​</a></h3><p><strong>GoR</strong> 方案构建了论文引用演化图谱，微调模型效果超过 GPT-4o。研究涵盖顶级会议七千篇参考数据，显著降低了学术创新门槛 (ฅ՞•ﻌ•՞ฅ) 来源：<a href="https://arxiv.org/abs/2605.14790" target="_blank" rel="noreferrer">论文</a></p><h3 id="_3-代码代理可作为物理世界模拟器" tabindex="-1">3. 代码代理可作为物理世界模拟器 <a class="header-anchor" href="#_3-代码代理可作为物理世界模拟器" aria-label="Permalink to &quot;3. 代码代理可作为物理世界模拟器&quot;">​</a></h3><p>研究发现视频模型往往难以维持物理约束，而<strong>代码生成系统驱动的可执行仿真环境</strong>在具身智能领域表现远超视频模型，代码驱动正成为模拟现实的新范式 (´･ω･`) 来源：<a href="https://arxiv.org/abs/2605.14398" target="_blank" rel="noreferrer">论文</a></p><h3 id="_4-具身智能体-ash-实现自我进化突破" tabindex="-1">4. 具身智能体 ASH 实现自我进化突破 <a class="header-anchor" href="#_4-具身智能体-ash-实现自我进化突破" aria-label="Permalink to &quot;4. 具身智能体 ASH 实现自我进化突破&quot;">​</a></h3><p>智能体 <strong>ASH</strong> 成功利用视频实现自我进化，系统借助逆动力学从噪声中提取监督信号，在宝可梦测评中完美达成任务，为自进化路径提供了全新可扩展范式 (⊙o⊙) 来源：<a href="https://arxiv.org/abs/2605.14211" target="_blank" rel="noreferrer">论文</a></p><h3 id="_5-articraft-ai-驱动的关节-3d-资产生成系统" tabindex="-1">5. Articraft：AI 驱动的关节 3D 资产生成系统 <a class="header-anchor" href="#_5-articraft-ai-驱动的关节-3d-资产生成系统" aria-label="Permalink to &quot;5. Articraft：AI 驱动的关节 3D 资产生成系统&quot;">​</a></h3><p>剑桥大学、牛津大学和南洋理工联合发布 <strong>Articraft</strong>——将 3D 资产生成转化为代码生成问题，让 LLM 编写 Python 程序构建可活动 3D 资产。同步开源 <strong>Articraft-10K</strong> 数据集（超 1 万资产、245 类别），CC-BY 4.0 协议，论文发表于 arXiv 🤖 来源：<a href="https://arxiv.org/abs/2605.15187" target="_blank" rel="noreferrer">论文</a> · <a href="https://github.com/mattzh72/articraft" target="_blank" rel="noreferrer">GitHub</a></p><h3 id="_6-rxeval-医疗处方推荐基准发布" tabindex="-1">6. RxEval 医疗处方推荐基准发布 <a class="header-anchor" href="#_6-rxeval-医疗处方推荐基准发布" aria-label="Permalink to &quot;6. RxEval 医疗处方推荐基准发布&quot;">​</a></h3><p>全新针对<strong>处方推荐</strong>的基准正式发布。测试涵盖九百多种药物，旧测评无法模拟真实临床环境，顶级模型在测试中表现堪忧——模型容易忽略病历核心细节 (·•᷄\\u200Eࡇ•᷅ ) 来源：<a href="https://arxiv.org/abs/2605.14543" target="_blank" rel="noreferrer">论文</a></p><h2 id="行业、政策与安全" tabindex="-1">行业、政策与安全 <a class="header-anchor" href="#行业、政策与安全" aria-label="Permalink to &quot;行业、政策与安全&quot;">​</a></h2><h3 id="_1-突发-openai-大规模重组-总裁-brockman-夺权挂帅" tabindex="-1">1. 突发！OpenAI 大规模重组，总裁 Brockman 夺权挂帅 <a class="header-anchor" href="#_1-突发-openai-大规模重组-总裁-brockman-夺权挂帅" aria-label="Permalink to &quot;1. 突发！OpenAI 大规模重组，总裁 Brockman 夺权挂帅&quot;">​</a></h3><p><strong>OpenAI</strong> 宣布史上最大规模重组，将 ChatGPT、Codex 和 API 三大核心产品线合并为统一组织。联合创始人兼总裁 <strong>Greg Brockman</strong> 正式全面接管产品战略，成为实际掌权者，原 ChatGPT 负责人 Nick Turley 被调离核心岗位。此次重组旨在聚焦「智能体时代」，秘密开发集成多项功能的桌面端「<strong>超级应用</strong>」🚀</p><p><img src="'+s+'" alt="AI资讯：OpenAI联合创始人兼总裁Greg Brockman重归一线接管产品战略" loading="lazy"></p><p>来源：<a href="https://www.ithome.com/0/951/258.htm" target="_blank" rel="noreferrer">IT 之家报道</a></p><h3 id="_2-anthropic-寻求-900b-估值融资-年化收入首超-openai" tabindex="-1">2. Anthropic 寻求 $900B 估值融资，年化收入首超 OpenAI <a class="header-anchor" href="#_2-anthropic-寻求-900b-估值融资-年化收入首超-openai" aria-label="Permalink to &quot;2. Anthropic 寻求 $900B 估值融资，年化收入首超 OpenAI&quot;">​</a></h3><p>据 <strong>Bloomberg</strong> 和 <strong>FT</strong> 报道，<strong>Anthropic</strong> 正寻求以约 $900B 估值进行 $30-50B 新一轮融资，由 Sequoia、Dragoneer 等联合领投。Anthropic 年化收入已超 $45B，首超 OpenAI 的 $24B，其中 Claude Code 贡献超 $2.5B。公司目标最早于 2026 年 10 月 IPO 🤑 来源：<a href="https://in.marketscreener.com/news/anthropic-weighs-new-funding-round-at-valuation-exceeding-900-billion-bloomberg-news-reports-ce7f58dad08af020" target="_blank" rel="noreferrer">Bloomberg 报道</a> · <a href="https://www.cnbctv18.com/business/companies/anthropic-considering-funding-offers-at-over-900-billion-value-chatgpt-artificial-intelligence-openai-mythos-google-cybersecurity-ws-l-19896306.htm" target="_blank" rel="noreferrer">CNBC TV18</a> · <a href="https://www.moneycontrol.com/artificial-intelligence/anthropic-nears-30-bn-funding-round-at-900-bn-valuation-may-surpass-openai-report-article-13920124.html" target="_blank" rel="noreferrer">Moneycontrol</a></p><h3 id="_3-mythos-辅助发现-macos-m5-内核漏洞-5-天绕过苹果-mie" tabindex="-1">3. Mythos 辅助发现 macOS M5 内核漏洞，5 天绕过苹果 MIE <a class="header-anchor" href="#_3-mythos-辅助发现-macos-m5-内核漏洞-5-天绕过苹果-mie" aria-label="Permalink to &quot;3. Mythos 辅助发现 macOS M5 内核漏洞，5 天绕过苹果 MIE&quot;">​</a></h3><p>安全初创公司 <strong>Calif</strong> 使用 Anthropic <strong>Claude Mythos Preview</strong>，在仅 <strong>5 天</strong>内开发出针对 Apple M5 芯片 <strong>Memory Integrity Enforcement（MIE）</strong> 的 macOS 内核提权漏洞利用链。这是 MIE 硬件安全机制自 2025 年 9 月推出以来首次被公开攻破。Mythos 协助识别漏洞并辅助开发全过程，但最终绕过 MIE 仍需人类专家参与 ⚠️ 来源：<a href="https://www.ithome.com/0/950/676.htm" target="_blank" rel="noreferrer">IT 之家报道</a> · <a href="https://www.scworld.com/brief/researchers-bypass-apples-m5-security-with-ai-powered-macos-exploit" target="_blank" rel="noreferrer">SCWorld</a> · <a href="https://tech.yahoo.com/cybersecurity/articles/first-apple-m5-memory-exploit-110000676.html" target="_blank" rel="noreferrer">Yahoo Tech</a></p><h3 id="_4-美国开始出现-ai-相关岗位大规模裁员" tabindex="-1">4. 美国开始出现 AI 相关岗位大规模裁员 <a class="header-anchor" href="#_4-美国开始出现-ai-相关岗位大规模裁员" aria-label="Permalink to &quot;4. 美国开始出现 AI 相关岗位大规模裁员&quot;">​</a></h3><p>据<strong>彭博社</strong>报道，受 AI 影响的职位正经历严重的就业岗位流失，技术冲击已从理论讨论进入现实阶段，具体裁员数字和涉及行业领域正在进一步显现 ⚠️ 来源：<a href="https://www.bloomberg.com/news/articles/2026-05-15/us-is-starting-to-see-heavy-job-losses-in-roles-exposed-to-ai" target="_blank" rel="noreferrer">Bloomberg 报道</a></p><h3 id="_5-杭州启用国家级具身智能机器人训练场" tabindex="-1">5. 杭州启用国家级具身智能机器人训练场 <a class="header-anchor" href="#_5-杭州启用国家级具身智能机器人训练场" aria-label="Permalink to &quot;5. 杭州启用国家级具身智能机器人训练场&quot;">​</a></h3><p>国家人工智能应用中试基地（具身智能）5 月 16 日在<strong>浙江杭州</strong>挂牌启用。杭州已施行首部具身智能机器人地方性法规，集聚机器人企业 700 余家，2025 年具身智能产业集群产值达 <strong>1068 亿元</strong> (๑•̀ㅂ•́)و✧ 来源：<a href="https://www.ithome.com/0/951/390.htm" target="_blank" rel="noreferrer">IT 之家报道</a></p><h3 id="_6-openai-与马耳他合作-向所有公民提供-chatgpt-plus" tabindex="-1">6. OpenAI 与马耳他合作，向所有公民提供 ChatGPT Plus <a class="header-anchor" href="#_6-openai-与马耳他合作-向所有公民提供-chatgpt-plus" aria-label="Permalink to &quot;6. OpenAI 与马耳他合作，向所有公民提供 ChatGPT Plus&quot;">​</a></h3><p><strong>OpenAI</strong> 与马耳他政府达成合作，将向该国所有公民免费提供 <strong>ChatGPT Plus</strong> 订阅服务，并包含 AI 技能实践培训。这是国家级大规模推广 ChatGPT Plus 的首例 ☁️ 来源：<a href="https://openai.com/index/malta-chatgpt-plus-partnership" target="_blank" rel="noreferrer">OpenAI 官方公告</a></p><h3 id="_7-iiq-企业-ai-影响力评估框架" tabindex="-1">7. IIQ 企业 AI 影响力评估框架 <a class="header-anchor" href="#_7-iiq-企业-ai-影响力评估框架" aria-label="Permalink to &quot;7. IIQ 企业 AI 影响力评估框架&quot;">​</a></h3><p><strong>IIQ 框架</strong>提出用「采用指数」取代传统词元统计来评估组织 AI 集成深度，综合考量任务难度与自主性，为工作流嵌入 AI 提供了财务视角 ( •̀ ω •́ )y 来源：<a href="https://arxiv.org/abs/2605.14455" target="_blank" rel="noreferrer">论文</a></p><h3 id="_8-亦庄-ai-实战大会即将在北京开幕" tabindex="-1">8. 亦庄 AI 实战大会即将在北京开幕 <a class="header-anchor" href="#_8-亦庄-ai-实战大会即将在北京开幕" aria-label="Permalink to &quot;8. 亦庄 AI 实战大会即将在北京开幕&quot;">​</a></h3><p>「亦庄 AI 落地实战大会」主打全干货，大咖现场拆解具身智能案例，彻底告别 PPT，主打<strong>压力测试</strong>，推动行业场景渗透 (ง •_•)ง 来源：<a href="https://www.qbitai.com/2026/05/418620.html" target="_blank" rel="noreferrer">详情</a></p><h2 id="开源与开发者工具" tabindex="-1">开源与开发者工具 <a class="header-anchor" href="#开源与开发者工具" aria-label="Permalink to &quot;开源与开发者工具&quot;">​</a></h2><h3 id="_1-智能体框架-superpowers-霸榜-🌟190k" tabindex="-1">1. 智能体框架 Superpowers 霸榜 🌟190k <a class="header-anchor" href="#_1-智能体框架-superpowers-霸榜-🌟190k" aria-label="Permalink to &quot;1. 智能体框架 Superpowers 霸榜 🌟190k&quot;">​</a></h3><p>智能体技能框架 <strong>Superpowers</strong> 在开源平台霸榜，星数突破惊人的 19 万。项目通过 Agentic 架构重塑开发流程，开发者持续涌入 (๑•̀ㅂ•́)و✧ 来源：<a href="https://github.com/obra/superpowers" target="_blank" rel="noreferrer">Superpowers 项目</a></p><p><img src="'+i+'" alt="AI资讯：开发者群体正在涌入GitHub查看superpowers项目的智能体协作流程" loading="lazy"></p><h3 id="_2-开源视频生成平台-open-generative-ai-🌟14-4k" tabindex="-1">2. 开源视频生成平台 Open-Generative-AI 🌟14.4k <a class="header-anchor" href="#_2-开源视频生成平台-open-generative-ai-🌟14-4k" aria-label="Permalink to &quot;2. 开源视频生成平台 Open-Generative-AI 🌟14.4k&quot;">​</a></h3><p>聚合了 <strong>Flux</strong> 和 <strong>Sora</strong> 等主流架构的开源视频生成工作站，支持私有化部署且无任何限制 (・ω・) 来源：<a href="https://github.com/Anil-matcha/Open-Generative-AI" target="_blank" rel="noreferrer">项目地址</a></p><p><img src="'+l+'" alt="AI资讯：Open-Generative-AI展示了聚合Flux、Sora等多种模型的开源工作站界面" loading="lazy"></p><h3 id="_3-本地代码图谱-codegraph-提升效率-🌟2-5k" tabindex="-1">3. 本地代码图谱 codegraph 提升效率 🌟2.5k <a class="header-anchor" href="#_3-本地代码图谱-codegraph-提升效率-🌟2-5k" aria-label="Permalink to &quot;3. 本地代码图谱 codegraph 提升效率 🌟2.5k&quot;">​</a></h3><p>配合 <strong>Claude Code</strong> 使用的本地索引利器，可预索引代码大幅减少 Token 消耗，100% 本地运行且完全免费 (〃&#39;▽&#39;〃) 来源：<a href="https://github.com/colbymchenry/codegraph" target="_blank" rel="noreferrer">codegraph 项目</a></p><p><img src="'+h+'" alt="AI资讯：将复杂代码库转化为结构化本地知识图谱以降低检索成本" loading="lazy"></p><h2 id="社媒与观点" tabindex="-1">社媒与观点 <a class="header-anchor" href="#社媒与观点" aria-label="Permalink to &quot;社媒与观点&quot;">​</a></h2><h3 id="_1-防护-ai-智能体遭受指令劫持" tabindex="-1">1. 防护 AI 智能体遭受指令劫持 <a class="header-anchor" href="#_1-防护-ai-智能体遭受指令劫持" aria-label="Permalink to &quot;1. 防护 AI 智能体遭受指令劫持&quot;">​</a></h3><p>智能体容易被恶意网页注入指令<strong>接管控制权</strong>，隐藏代码会窃取凭证甚至修改行为。目前必须采用源感知授权机制防护，开发者可用一行代码集成沙箱保护环境 (つ•̀ω•́)つ 来源：<a href="https://www.reddit.com/r/artificial/comments/1teytyb/your_ai_agent_is_one_poisoned_webpage_away_from/" target="_blank" rel="noreferrer">Reddit 讨论</a></p><h3 id="_2-最新开源成果-21-开源模型密集发布" tabindex="-1">2. 最新开源成果 #21：开源模型密集发布 <a class="header-anchor" href="#_2-最新开源成果-21-开源模型密集发布" aria-label="Permalink to &quot;2. 最新开源成果 #21：开源模型密集发布&quot;">​</a></h3><p>本月开源 AI 模型迎来盛宴——<strong>Gemma 4</strong>、<strong>DeepSeek V4</strong>、<strong>Kimi K2.6</strong>、<strong>MiMo 2.5</strong>、<strong>GLM-5.1</strong> 等一系列重要新版本密集发布，均在 CAISI V4 评估框架下完成评测 🚀 来源：<a href="https://www.interconnects.ai/p/latest-open-artifacts-21-open-model" target="_blank" rel="noreferrer">Interconnects 报道</a></p><h3 id="_3-anthropic-发布《founder-s-playbook》-ai-时代创业失败率更高" tabindex="-1">3. Anthropic 发布《Founder&#39;s Playbook》：AI 时代创业失败率更高 <a class="header-anchor" href="#_3-anthropic-发布《founder-s-playbook》-ai-时代创业失败率更高" aria-label="Permalink to &quot;3. Anthropic 发布《Founder&#39;s Playbook》：AI 时代创业失败率更高&quot;">​</a></h3><p><strong>Anthropic</strong> 于 5 月 14 日发布 33 页创业手册，将 AI 原生创业拆解为 Idea → MVP → Launch → Scale 四阶段。手册引用数据指出 42% 的创业公司死于&quot;做了没人要的东西&quot;，并警告<strong>在 AI 时代失败率只会继续攀升</strong>——从想法到产品的距离被压缩到几乎为零，创始人极易把&quot;做出来了&quot;误认为&quot;验证通过了&quot; (•̀ᴗ•́)و 来源：<a href="https://claude.com/blog/the-founders-playbook" target="_blank" rel="noreferrer">官方博客</a> · <a href="https://help.apiyi.com/anthropic-founders-playbook-ai-native-startup-deep-analysis.html" target="_blank" rel="noreferrer">中文解读</a></p><h3 id="快讯" tabindex="-1">快讯 <a class="header-anchor" href="#快讯" aria-label="Permalink to &quot;快讯&quot;">​</a></h3><ul><li><p><strong>奥特曼个人崇拜导致公司陷入危机。</strong> 社区热议 OpenAI 管理层路径依赖问题，未来属于能将技术嵌入工作流的务实者 <a href="https://www.reddit.com/r/artificial/comments/1tex4pw/sam_altmans_ego_was_openais_downfall/" target="_blank" rel="noreferrer">Reddit 讨论</a></p></li><li><p><strong>Show HN: 烧吧，宝贝，烧吧（那些代币）。</strong> 开源销毁代币工具，在 HN 上获得 100 点社区热度 🔥 <a href="https://github.com/dtnewman/burn-baby-burn" target="_blank" rel="noreferrer">GitHub</a></p></li></ul><h2 id="今日总结与启示" tabindex="-1">今日总结与启示 <a class="header-anchor" href="#今日总结与启示" aria-label="Permalink to &quot;今日总结与启示&quot;">​</a></h2><ul><li><strong>AI 两巨头同日上演权力与资本双重变局。</strong> OpenAI 重组 Brockman 掌权，Anthropic 估值 $900B 年化收入反超——竞争格局正在从技术之争升维为组织与资本的全方位对决 🚀。</li><li><strong>网络安全攻防进入 AI 军备竞赛。</strong> GPT-5.5 CTF 成功率 71.4% 匹敌 Mythos，且 Mythos 已在实战中 5 天攻破 M5 硬件安全。攻防双方的时间窗口正在被 AI 急剧压缩 ⚠️。</li><li><strong>中国万亿参数模型以 MIT 协议全面开源。</strong> 蚂蚁 Ring-2.6-1T 在基准超越 GPT-5.4 的同时选择最宽松许可，开源模型的技术水位与开放程度同步攀升 (๑•̀ㅂ•́)و✧。</li><li><strong>开发者工具进入 Agent 原生时代。</strong> Notion 推出 Agent API + ntn CLI，Superpowers 190k 星——生产力工具正从&quot;人操作&quot;转向&quot;Agent 编排&quot; 🛠️。</li><li><strong>AI 对劳动力市场的冲击从预测变成数据。</strong> 彭博社首次以实证方式确认美国 AI 相关岗位大规模裁员，杭州具身智能基地千亿产值则展示了另一面——新产业也在同时创造新岗位 ( •̀ ω •́ )。</li></ul>',70)])])}const k=e(p,[["render",c]]);export{_ as __pageData,k as default};
